message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "You had a knee replacement on your right knee.",
          "sources": ["p1:L2", "term:TKA"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b2",
          "text": "Put weight on your leg if it feels okay. Use a walker.",
          "sources": ["p1:L11", "term:WBAT"]
        },
        {
          "id": "b3",
          "text": "Do exercises to help you move better three times a week.",
          "sources": ["p1:L11", "term:PT"]
        },
        {
          "id": "b4",
          "text": "Ice your knee for 20 minutes every 2 hours.",
          "sources": ["p1:L11"]
        },
        {
          "id": "b5",
          "text": "Keep your leg raised up.",
          "sources": ["p1:L11"]
        },
        {
          "id": "b6",
          "text": "Keep the bandage dry. No tub baths or swimming until staples are taken out.",
          "sources": ["p1:L12"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b7",
          "text": "See the bone doctor. Go in 2 weeks. This visit is to take out the staples.",
          "sources": ["p1:L13"]
        }
      ]
    }
  ],
  "questions_for_your_doctor": [
    "When can I stop using the walker?",
    "How long should I keep icing my knee?",
    "What should I do if the bandage gets wet?"
  ]
}
